"""GENERATED level-2 RMSNorm structural kernel (GM-assembly route, Form D).
BATCH=1 rows, D=512 = 4 chains x 2 tiles x 64 lanes.
A SimdVF region per row returns the per-tile UB values as a Tuple; OUTSIDE the VF,
tf.insert_slice assembles them into the GM output (per-tile T.copy, no whole-block copy).
Weight is staged bf16 and converted to f32 INSIDE the main VF per output tile. NOTE: a
separate weight-VF (bf16->f32 into a wf UB once) is NOT done in this structural route; it
needs the deferred UB-row aggregation capability (P5 boundary) and is recorded as a known
deviation. acc=vmula(v,v,mask,acc) reads the previous acc (READ|WRITE SSA carry)."""
from __future__ import annotations
from tilefoundry.dsl import *
from tilefoundry_ascend import Ascend950PRTarget

L = 64
CHAINS = 4
TPC = 2
TILES = CHAINS * TPC
BATCH = 1
D = TILES * L
EPS = 1e-6

@module(entry="rmsnorm", target=Ascend950PRTarget(), topologies=(Topology("aiv", 1),))
class RMSNormD:
    @func
    def rmsnorm(x: Tensor[(BATCH * D,), "bf16"], w: Tensor[(D,), "bf16"]) -> Tensor[(BATCH * D,), "bf16"]:
        with Mesh(("aiv",), layout=(1,), names=("core",)) as aiv:
            out = tf.empty(Tensor[(BATCH * D,), "bf16", (BATCH * D,), "gmem"])
            for r in tf.tile(BATCH, 1):
                row = r + 0
                ux0 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx0 = tf.schedule((x[row * D + 0 * L:row * D + 0 * L + L], ux0), op=T.ascend_gm_to_ub())
                ux1 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx1 = tf.schedule((x[row * D + 1 * L:row * D + 1 * L + L], ux1), op=T.ascend_gm_to_ub())
                ux2 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx2 = tf.schedule((x[row * D + 2 * L:row * D + 2 * L + L], ux2), op=T.ascend_gm_to_ub())
                ux3 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx3 = tf.schedule((x[row * D + 3 * L:row * D + 3 * L + L], ux3), op=T.ascend_gm_to_ub())
                ux4 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx4 = tf.schedule((x[row * D + 4 * L:row * D + 4 * L + L], ux4), op=T.ascend_gm_to_ub())
                ux5 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx5 = tf.schedule((x[row * D + 5 * L:row * D + 5 * L + L], ux5), op=T.ascend_gm_to_ub())
                ux6 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx6 = tf.schedule((x[row * D + 6 * L:row * D + 6 * L + L], ux6), op=T.ascend_gm_to_ub())
                ux7 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sx7 = tf.schedule((x[row * D + 7 * L:row * D + 7 * L + L], ux7), op=T.ascend_gm_to_ub())
                uw0 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw0 = tf.schedule((w[0 * L:0 * L + L], uw0), op=T.ascend_gm_to_ub())
                uw1 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw1 = tf.schedule((w[1 * L:1 * L + L], uw1), op=T.ascend_gm_to_ub())
                uw2 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw2 = tf.schedule((w[2 * L:2 * L + L], uw2), op=T.ascend_gm_to_ub())
                uw3 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw3 = tf.schedule((w[3 * L:3 * L + L], uw3), op=T.ascend_gm_to_ub())
                uw4 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw4 = tf.schedule((w[4 * L:4 * L + L], uw4), op=T.ascend_gm_to_ub())
                uw5 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw5 = tf.schedule((w[5 * L:5 * L + L], uw5), op=T.ascend_gm_to_ub())
                uw6 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw6 = tf.schedule((w[6 * L:6 * L + L], uw6), op=T.ascend_gm_to_ub())
                uw7 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                sw7 = tf.schedule((w[7 * L:7 * L + L], uw7), op=T.ascend_gm_to_ub())
                with T.SimdVF():
                    m32 = tf.empty(Tensor[(L,), "bool", (L,), "rmem"])
                    p32 = tf.schedule((m32,), op=T.ascend_pset(elem_width=32))
                    m16 = tf.empty(Tensor[(L,), "bool", (L,), "rmem"])
                    p16 = tf.schedule((m16,), op=T.ascend_pset16(elem_width=16))
                    m16b = tf.empty(Tensor[(L,), "bool", (L,), "rmem"])
                    p16b = tf.schedule((m16b,), op=T.ascend_pset16(elem_width=16))
                    cx0 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx0 = tf.schedule((sx0, cx0), op=T.ascend_vld(dist="UNPK_B16"))
                    f0 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v0 = tf.schedule((lx0, p16, f0), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    cx1 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx1 = tf.schedule((sx1, cx1), op=T.ascend_vld(dist="UNPK_B16"))
                    f1 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v1 = tf.schedule((lx1, p16, f1), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    cx2 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx2 = tf.schedule((sx2, cx2), op=T.ascend_vld(dist="UNPK_B16"))
                    f2 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v2 = tf.schedule((lx2, p16, f2), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    cx3 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx3 = tf.schedule((sx3, cx3), op=T.ascend_vld(dist="UNPK_B16"))
                    f3 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v3 = tf.schedule((lx3, p16, f3), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    cx4 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx4 = tf.schedule((sx4, cx4), op=T.ascend_vld(dist="UNPK_B16"))
                    f4 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v4 = tf.schedule((lx4, p16, f4), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    cx5 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx5 = tf.schedule((sx5, cx5), op=T.ascend_vld(dist="UNPK_B16"))
                    f5 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v5 = tf.schedule((lx5, p16, f5), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    cx6 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx6 = tf.schedule((sx6, cx6), op=T.ascend_vld(dist="UNPK_B16"))
                    f6 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v6 = tf.schedule((lx6, p16, f6), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    cx7 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    lx7 = tf.schedule((sx7, cx7), op=T.ascend_vld(dist="UNPK_B16"))
                    f7 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    v7 = tf.schedule((lx7, p16, f7), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    acc_0 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    acc_0 = tf.schedule((v0, v0, p32, acc_0), op=T.ascend_vmula())
                    acc_0 = tf.schedule((v1, v1, p32, acc_0), op=T.ascend_vmula())
                    acc_1 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    acc_1 = tf.schedule((v2, v2, p32, acc_1), op=T.ascend_vmula())
                    acc_1 = tf.schedule((v3, v3, p32, acc_1), op=T.ascend_vmula())
                    acc_2 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    acc_2 = tf.schedule((v4, v4, p32, acc_2), op=T.ascend_vmula())
                    acc_2 = tf.schedule((v5, v5, p32, acc_2), op=T.ascend_vmula())
                    acc_3 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    acc_3 = tf.schedule((v6, v6, p32, acc_3), op=T.ascend_vmula())
                    acc_3 = tf.schedule((v7, v7, p32, acc_3), op=T.ascend_vmula())
                    mg0 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    mg0_r = tf.schedule((acc_0, acc_1, p32, mg0), op=T.ascend_vadd())
                    mg1 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    mg1_r = tf.schedule((acc_2, acc_3, p32, mg1), op=T.ascend_vadd())
                    mg2 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    mg2_r = tf.schedule((mg0_r, mg1_r, p32, mg2), op=T.ascend_vadd())
                    c0 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    c0_r = tf.schedule((mg2_r, c0), op=T.ascend_vcadd(lanes=64))
                    c1 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    c1_r = tf.schedule((c0_r, c1), op=T.ascend_vcadd(lanes=32))
                    c2 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    c2_r = tf.schedule((c1_r, c2), op=T.ascend_vcadd(lanes=16))
                    c3 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    c3_r = tf.schedule((c2_r, c3), op=T.ascend_vcadd(lanes=8))
                    c4 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    c4_r = tf.schedule((c3_r, c4), op=T.ascend_vcadd(lanes=4))
                    c5 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    c5_r = tf.schedule((c4_r, c5), op=T.ascend_vcadd(lanes=2))
                    br = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    bbr = tf.schedule((c5_r, br), op=T.ascend_vdupv(position=0))
                    mean = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    meanr = tf.schedule((bbr, p32, mean), op=T.ascend_vmuls(value=1.0 / D))
                    shf = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    shfr = tf.schedule((meanr, p32, shf), op=T.ascend_vadds(value=EPS))
                    rt = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    rtr = tf.schedule((shfr, p32, rt), op=T.ascend_vsqrt())
                    one = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    oner = tf.schedule((p32, one), op=T.ascend_vdup(value=1.0))
                    rstd = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    rstdr = tf.schedule((oner, rtr, p32, rstd), op=T.ascend_vdiv())
                    wc0 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl0 = tf.schedule((sw0, wc0), op=T.ascend_vld(dist="UNPK_B16"))
                    wf0 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv0 = tf.schedule((wl0, p16, wf0), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr0 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr0 = tf.schedule((v0, rstdr, p32, xr0), op=T.ascend_vmul())
                    o0 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov0 = tf.schedule((xrr0, wv0, p32, o0), op=T.ascend_vmul())
                    rc0 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv0 = tf.schedule((ov0, p16b, rc0), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo0 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt0 = tf.schedule((rv0, uo0), op=T.ascend_vsts(pack="PK_B32"))
                    wc1 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl1 = tf.schedule((sw1, wc1), op=T.ascend_vld(dist="UNPK_B16"))
                    wf1 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv1 = tf.schedule((wl1, p16, wf1), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr1 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr1 = tf.schedule((v1, rstdr, p32, xr1), op=T.ascend_vmul())
                    o1 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov1 = tf.schedule((xrr1, wv1, p32, o1), op=T.ascend_vmul())
                    rc1 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv1 = tf.schedule((ov1, p16b, rc1), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo1 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt1 = tf.schedule((rv1, uo1), op=T.ascend_vsts(pack="PK_B32"))
                    wc2 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl2 = tf.schedule((sw2, wc2), op=T.ascend_vld(dist="UNPK_B16"))
                    wf2 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv2 = tf.schedule((wl2, p16, wf2), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr2 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr2 = tf.schedule((v2, rstdr, p32, xr2), op=T.ascend_vmul())
                    o2 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov2 = tf.schedule((xrr2, wv2, p32, o2), op=T.ascend_vmul())
                    rc2 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv2 = tf.schedule((ov2, p16b, rc2), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo2 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt2 = tf.schedule((rv2, uo2), op=T.ascend_vsts(pack="PK_B32"))
                    wc3 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl3 = tf.schedule((sw3, wc3), op=T.ascend_vld(dist="UNPK_B16"))
                    wf3 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv3 = tf.schedule((wl3, p16, wf3), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr3 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr3 = tf.schedule((v3, rstdr, p32, xr3), op=T.ascend_vmul())
                    o3 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov3 = tf.schedule((xrr3, wv3, p32, o3), op=T.ascend_vmul())
                    rc3 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv3 = tf.schedule((ov3, p16b, rc3), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo3 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt3 = tf.schedule((rv3, uo3), op=T.ascend_vsts(pack="PK_B32"))
                    wc4 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl4 = tf.schedule((sw4, wc4), op=T.ascend_vld(dist="UNPK_B16"))
                    wf4 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv4 = tf.schedule((wl4, p16, wf4), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr4 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr4 = tf.schedule((v4, rstdr, p32, xr4), op=T.ascend_vmul())
                    o4 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov4 = tf.schedule((xrr4, wv4, p32, o4), op=T.ascend_vmul())
                    rc4 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv4 = tf.schedule((ov4, p16b, rc4), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo4 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt4 = tf.schedule((rv4, uo4), op=T.ascend_vsts(pack="PK_B32"))
                    wc5 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl5 = tf.schedule((sw5, wc5), op=T.ascend_vld(dist="UNPK_B16"))
                    wf5 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv5 = tf.schedule((wl5, p16, wf5), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr5 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr5 = tf.schedule((v5, rstdr, p32, xr5), op=T.ascend_vmul())
                    o5 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov5 = tf.schedule((xrr5, wv5, p32, o5), op=T.ascend_vmul())
                    rc5 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv5 = tf.schedule((ov5, p16b, rc5), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo5 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt5 = tf.schedule((rv5, uo5), op=T.ascend_vsts(pack="PK_B32"))
                    wc6 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl6 = tf.schedule((sw6, wc6), op=T.ascend_vld(dist="UNPK_B16"))
                    wf6 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv6 = tf.schedule((wl6, p16, wf6), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr6 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr6 = tf.schedule((v6, rstdr, p32, xr6), op=T.ascend_vmul())
                    o6 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov6 = tf.schedule((xrr6, wv6, p32, o6), op=T.ascend_vmul())
                    rc6 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv6 = tf.schedule((ov6, p16b, rc6), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo6 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt6 = tf.schedule((rv6, uo6), op=T.ascend_vsts(pack="PK_B32"))
                    wc7 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    wl7 = tf.schedule((sw7, wc7), op=T.ascend_vld(dist="UNPK_B16"))
                    wf7 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    wv7 = tf.schedule((wl7, p16, wf7), op=T.ascend_vcvt(direction="forward", part=0, elem_width=16))
                    xr7 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    xrr7 = tf.schedule((v7, rstdr, p32, xr7), op=T.ascend_vmul())
                    o7 = tf.empty(Tensor[(L,), "f32", (L,), "rmem"])
                    ov7 = tf.schedule((xrr7, wv7, p32, o7), op=T.ascend_vmul())
                    rc7 = tf.empty(Tensor[(L,), "bf16", (L,), "carrier"])
                    rv7 = tf.schedule((ov7, p16b, rc7), op=T.ascend_vcvt(direction="reverse", part=0, elem_width=16))
                    uo7 = tf.empty(Tensor[(L,), "bf16", (L,), "smem"])
                    wvt7 = tf.schedule((rv7, uo7), op=T.ascend_vsts(pack="PK_B32"))
                a0 = tf.insert_slice(out, wvt0, (row * D + 0 * L,))
                a1 = tf.insert_slice(a0, wvt1, (row * D + 1 * L,))
                a2 = tf.insert_slice(a1, wvt2, (row * D + 2 * L,))
                a3 = tf.insert_slice(a2, wvt3, (row * D + 3 * L,))
                a4 = tf.insert_slice(a3, wvt4, (row * D + 4 * L,))
                a5 = tf.insert_slice(a4, wvt5, (row * D + 5 * L,))
                a6 = tf.insert_slice(a5, wvt6, (row * D + 6 * L,))
                a7 = tf.insert_slice(a6, wvt7, (row * D + 7 * L,))
                out = a7
            return out